-- Mesas 01 a 20 (para os QR Codes /mesa/01 ... /mesa/20)
select g.n, 'Mesa ' || lpad(g.n::text, 2, '0'), true
from generate_series(1, 20) as g(n)
on conflict (number) do nothing;
















































