insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000250', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-00000000024f', '1091', 'Bolinhos de bacalhau', 'Iguaria da cozinha portuguesa com toque especial da casa, douradas e crocantes, preparadas com bacalhau desfiado e ervas frescas.', '6 unidades', 29.00, true, 1);
