insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000255', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-00000000024f', '572', 'Coxa ou sobrecoxa de frango', null, null, 10.50, true, 6);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000256', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-00000000024f', '1089', 'Mini pastel de carne', 'Crocantes pastéis artesanais recheados com carne bovina temperada na medida certa. Uma explosão de sabor em cada mordida! O favorito dos nossos clientes.', '6 unidades', 15.90, true, 7);
