insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000261', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-00000000025b', '665', 'Salada Tropical', 'Folhas frescas de alface americana, alface crespa, rúcula, azeitona preta, cubos de cenoura, fruta da estação e tiras de apresuntado em molho especial da casa.', null, 22.50, true, 3);
