insert into public.categories (id, menu_id, slug, name, description, sort_order) values ('beef0000-0000-4000-8000-000000000267', 'aaaaaaaa-0000-4000-8000-000000000003', 'menu-sertanejo', 'Menu Sertanejo', null, 3) on conflict (menu_id, slug) do update set name = excluded.name;
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000268', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '055', 'Carne de sol na manteiga da terra', 'Carne de sol fatiada e finalizada na manteiga de garrafa artesanal. Acompanha arroz de leite ou baião de dois à moda (com queijo de coalho e creme de nata), paçoca ou farofa de cuscuz e macaxeira à moda da casa.', '400g', 130.90, true, 1);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000269', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '057', 'Carne de sol sertaneja na brasa à moda', 'Carne de sol na manteiga de garrafa intercalada com queijo do sertão e banana à milanesa. Acompanha arroz de leite ou baião à moda (com queijo de coalho e creme de nata), macaxeira à moda da casa, farofa de cuscuz e vinagrete fresco.', '400g', 120.50, true, 2);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-00000000026a', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '522', 'Escondidinho de carne de sol', 'Camadas generosas de purê de macaxeira intercaladas com carne de sol desfiada e temperada, gratinada no forno até formar casquinha dourada. Acompanha arroz ou baião de dois e salada verde.', '400g', 109.90, true, 3);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-00000000026b', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '053', 'Bife acebolado', 'Bife bovino ao molho, coberto com cebolas refogadas na manteiga. Acompanha arroz, feijão, farofa de cuscuz, batata frita crocante e vinagrete.', '300g', 93.50, true, 4);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-00000000026c', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '052', 'Bife a cavalo', 'Bife bovino ao molho com ovos fritos por cima. Acompanha arroz, feijão, farofa de cuscuz, batata frita e salada verde.', '300g', 96.50, true, 5);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-00000000026d', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '261', 'Peixada sertaneja (tilápia)', 'Peixe fresco em postas cozido ao molho de leite de coco com tomates, pimentões e coentro. Acompanha arroz branco, feijão, pirão de peixe cremoso, ovos e legumes cozidos.', '900g', 113.90, true, 6);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-00000000026e', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '354', 'Guisado de carneiro completo', 'Carneiro cozido lentamente com batatas, cenouras, pimentão e temperos regionais até ficar macio. Molho encorpado e aromático. Acompanha arroz branco, feijão ou baião de dois, pirão cremoso ou farofa de cuscuz.', '700g', 91.50, true, 7);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-00000000026f', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '351', 'Buchada de carneiro', 'Especialidade rara da culinária sertaneja. Vísceras de carneiro temperadas com coentro fresco e pimenta-do-reino, cozidas na pressão até ficarem macias. Servida com arroz branco ou baião de dois, pirão ou farofa de cuscuz.', '500g', 98.90, true, 8);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000270', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '051', 'Bife ao molho especial da casa', 'Bife bovino de coxão mole. Acompanha arroz ou baião de dois, batata frita e salada verde.', '300g', 89.50, true, 9);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000271', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '529', 'Costelinha suína ao forno, regada com mel de engenho', 'Costela suína assada lentamente ao forno e regada com mel de engenho, criando uma caramelização brilhante. Acompanha arroz ou baião de dois, batata frita e vinagrete.', '600g', 87.50, true, 10);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000272', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '156', 'Galinha caipira ao molho', 'Galinha caipira cozida em ervas da região, lentamente, ao molho caseiro. Acompanha arroz ou baião de dois, farofa de cuscuz e pirão.', '700g', 79.50, true, 11);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000273', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '352', 'Costela de carneiro na brasa', 'Costela de carneiro assada lentamente na brasa de carvão até atingir o ponto perfeito: crosta dourada por fora, carne macia e suculenta por dentro. Acompanha arroz e feijão ou baião de dois, e farofa de cuscuz.', '600g', 87.50, true, 12);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000274', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '262', 'Tilápia na brasa', 'Tilápia inteira escalada, grelhada na brasa de carvão, temperada com sal grosso e ervas. Acompanha arroz e feijão ou baião de dois, batata frita e vinagrete. Porção generosa para compartilhar.', '900g', 108.90, true, 13);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000275', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '263', 'Tilápia frita', 'Acompanha arroz e feijão ou baião de dois, macaxeira à moda ou batata frita, farofa e vinagrete.', '900g', 106.90, true, 14);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000276', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000267', '063', 'Panelada', 'Prato tradicional da culinária nordestina, feito com miúdos de boi, bucho e vísceras, cozidos em molho saboroso com tempero da região. Acompanha arroz e feijão ou baião de dois, farofa de cuscuz e vinagrete.', '500g', 75.50, true, 15);
insert into public.categories (id, menu_id, slug, name, description, sort_order) values ('beef0000-0000-4000-8000-000000000277', 'aaaaaaaa-0000-4000-8000-000000000003', 'selecao-premium', '★ Seleção Premium do Chef', null, 4) on conflict (menu_id, slug) do update set name = excluded.name;
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000278', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000277', '058', 'Filé à parmegiana completo', 'Filé mignon empanado artesanalmente, talharim coberto com nosso exclusivo molho de tomate ao manjericão fresco, presunto e queijo, gratinado até dourar perfeitamente. Acompanha arroz branco ou à grega, purê de batata ou batata frita e salada verde. Serve até 3 pessoas.', '400g', 144.90, true, 1);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-000000000279', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000277', '509', 'Espeto misto completo', 'Explosão de sabores na brasa! Combinação irresistível de carnes: maminha, filé suíno macio, coxa e sobrecoxa de frango e linguiça mista. Tudo preparado na brasa para preservar os sucos naturais. Acompanha arroz branco e feijão ou baião de dois, macarrão ou farofa, salada verde e batata frita.', '750g', 115.90, true, 2);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-00000000027a', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-000000000277', '520', 'Picanha importada', 'Corte premium importado com marmoreio excepcional, garantindo maciez incomparável e sabor intenso. Grelhada na brasa ao ponto perfeito, preservando toda a suculência. A capa de gordura derrete lentamente. Acompanha arroz branco e feijão ou baião de dois, macarrão ou farofa, salada verde e batata frita.', '400g', 169.00, true, 3);
insert into public.categories (id, menu_id, slug, name, description, sort_order) values ('beef0000-0000-4000-8000-00000000027b', 'aaaaaaaa-0000-4000-8000-000000000003', 'pratos-executivos', 'Pratos Executivos', 'Escolha suas opções: arroz + feijão + macarrão ou baião e macarrão.', 5) on conflict (menu_id, slug) do update set name = excluded.name;
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-00000000027c', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-00000000027b', '623', 'Carne bovina assada', 'Carne bovina selecionada, grelhada na brasa com nosso blend secreto de temperos, mantendo todo o suco e maciez natural da carne. Selada perfeitamente por fora, suculenta por dentro.', '180g', 49.00, true, 1);
