insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-0000000002b5', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-0000000002b4', '061', 'Filé a medalhão', 'Medalhões de filé mignon selados ao molho especial do chef, preparado com ingredientes premium cuidadosamente selecionados. Textura que derrete na boca combinada com sabor sofisticado. Servido com arroz com brócolis ou à grega, purê de batata ou batata frita e salada verde.', '400g', 129.90, true, 1);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-0000000002b6', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-0000000002b4', '259', 'Filé de salmão na chapa ao molho de alcaparras', 'Generoso filé de salmão fresco grelhado ao ponto, coberto com nosso exclusivo molho de alcaparras e ervas finas. O salmão preserva sua textura delicada e sabor marcante, enquanto as alcaparras adicionam toque cítrico único. Prato premium para paladares exigentes. Servido com arroz com brócolis ou à grega, purê de batata ou salada verde.', '370g', 153.50, true, 2);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-0000000002b7', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-0000000002b4', '059', 'Filé ao molho madeira', 'Filé mignon premium ao clássico molho madeira com champignon fresco salteado. A combinação perfeita entre a maciez do filé e a profundidade aromática do molho madeira autêntico da casa. Um clássico da alta gastronomia em sua mesa. Servido com arroz com brócolis ou à grega, purê de batata ou batata frita e salada verde.', '400g', 127.90, true, 3);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-0000000002b8', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-0000000002b4', '523', 'Filé ao molho ouro negro', 'Filé mignon ao nosso exclusivo molho ouro negro — receita do Cacique que harmoniza sabores defumados, toques aromáticos e especiarias selecionadas. Servido com arroz com brócolis ou à grega, purê de abóbora e salada verde.', '400g', 127.90, true, 4);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-0000000002b9', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-0000000002b4', '530', 'Medalhão suíno à moda', 'Medalhões de filé suíno e fatias de bacon com queijo coalho ao ouro negro. Servido com arroz branco ou baião de dois, purê de batata ou salada tropical de frutas e verduras.', '400g', 114.90, true, 5);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-0000000002ba', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-0000000002b4', '253', 'Filé de peixe à delícia', 'Filé passado na farinha panko, com bananas ao toque de especiarias da casa envolto em molho branco, cobertura de queijo, gratinado. Servido com arroz branco, purê de batata ou salada verde.', '370g', 105.00, true, 6);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-0000000002bb', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-0000000002b4', '153', 'Filé de frango à parmegiana', 'Filé de frango empanado artesanalmente, talharim coberto com nosso exclusivo molho de tomate ao manjericão fresco com presunto e queijo gratinado até dourar perfeitamente. Servido com arroz branco ou à grega, purê de batata e salada verde.', '370g', 97.50, true, 7);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-0000000002bc', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-0000000002b4', '252', 'Filé de peixe na chapa', 'Filé de peixe fresco grelhado na chapa ao molho de maracujá. Servido com arroz com brócolis, purê de batata ou salada verde.', '370g', 89.50, true, 8);
insert into public.products (id, menu_id, category_id, code, name, description, size_label, price, active, sort_order) values ('beef0000-0000-4000-8000-0000000002bd', 'aaaaaaaa-0000-4000-8000-000000000003', 'beef0000-0000-4000-8000-0000000002b4', '622', 'Talharim à carbonara', 'Talharim recheado com bacon, queijo, creme de leite, gemas de ovos e queijo gratinado ao forno.', '750g', 65.50, true, 9);
insert into public.categories (id, menu_id, slug, name, description, sort_order) values ('beef0000-0000-4000-8000-0000000002be', 'aaaaaaaa-0000-4000-8000-000000000003', 'carnes-na-brasa', 'Carnes na Brasa', 'Carnes nobres grelhadas na brasa — escolha 3 guarnições: arroz, baião, feijão, macarrão, farofa de cuscuz ou fritas.', 7) on conflict (menu_id, slug) do update set name = excluded.name;
